import React from 'react'
import { Link } from 'react-router-dom'

const LessonItemRelated = ({ item }) => {

  return (
    <>
      <div className="col-md-3">
        <div className="lCItem">

          <div className="innerBx">
            <div className="titelBx">
              <i className="fa fa-lightbulb-o" />
              <h5>{item.title}</h5>
            </div>
            <div className="textCont">
              <p style={{ overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical" }}>{item.description}</p>
              <Link
                className="btn btnTheme width100 mt10"
                to={`/product/related-product/${item._id}`}
                style={{ background: "var(--theme-color)" }}
              >
                Start course
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

export default LessonItemRelated