import React, { useState } from "react";
import Ads from "../../../components/comon/Ads";
import { Link } from "react-router-dom";
import { Button, ProgressBar } from "react-bootstrap";
import { useAppContext } from "../../../contextApi/AppContext";
import AddProduct from "./AddProduct";
import { toast } from "react-toastify";

const AddPost = () => {
  const {
    serviceList,
    getSubServiceList,
    subServiceList,
    subServiceLoading,
    AddTitleDes,
  } = useAppContext();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({});
  const [inputData, setInputData] = useState({
    title: "",
    description: ""
  });

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setInputData({
      ...inputData,
      [name]: value,
    });
  };

  const dataToSend = {
    title: inputData.title,
    description: inputData.description,
    category_id: formData.servicecategories,
    sub_category_id: formData.subservicecat,
  };

  const handleNext = () => {
    if(step === 1 ){
      setStep(step + 1);
    }
    if (step === 2) {
      if (inputData.title && inputData.description && formData.servicecategories && formData.subservicecat ) {
        AddTitleDes(dataToSend);
        setStep(step + 1);
      }else{
        toast.warning("Please fill all the fields");
      }
    }
  };

  const handlePrevious = () => {
    setStep(step - 1);
  };

  const handleSelectCategory = (serviceId, subServiceId) => {
    setFormData({
      ...formData,
      servicecategories: serviceId,
      subservicecat: subServiceId,
    });
    handleNext();
  };

  const handleSubcat = (parId) => {
    getSubServiceList(parId);
  };

  return (
    <>
      <section className="pageBanner">
        <div className="container">
          <div className="row">
            <div className="col-md-6">
              <h4>Add Post</h4>
            </div>
            <div className="col-md-6">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li className="active">Add Post</li>
              </ul>
            </div>
          </div>
        </div>
      </section>
      <section className="midBody bgtheme">
        <div className="container-fluid">
          <div className="row">
            <Ads />
            <div className="col-md-10">
              <div className="card mt-0">
                <div className="card-header">
                  <h5>
                    {step === 1 ? "CHOOSE A CATEGORY" : "INCLUDE SOME DETAILS"}
                  </h5>
                </div>
                <div
                  className="card-body border-0"
                  style={{ minHeight: "500px" }}
                >
                  <ProgressBar now={(step / 3) * 100} label={`Step ${step}`} />
                  {step === 1 && (
                    <div className="postCategoryBx mt-5">
                      {Array.isArray(serviceList) &&
                        serviceList.map((item, index) => (
                          <div key={index} className="dropend">
                            <button
                              type="button"
                              className="dropdown-toggle btn btn-outline-primary"
                              data-bs-toggle="dropdown"
                              aria-expanded="false"
                              onClick={() => handleSubcat(item._id)}
                            >
                              {item.title}
                            </button>
                            <ul
                              className="dropdown-menu"
                              style={{ maxHeight: "250px", overflowY: "auto" }}
                            >
                              {subServiceLoading ? (
                                <div
                                  className="spinner-border text-primary text-center"
                                  role="status"
                                >
                                  <span className="sr-only">Loading...</span>
                                </div>
                              ) : (
                                Array.isArray(subServiceList) &&
                                subServiceList.map((item1) => (
                                  <li key={item1._id}>
                                    <Button
                                      className="dropdown-item"
                                      onClick={() =>
                                        handleSelectCategory(
                                          item._id,
                                          item1._id
                                        )
                                      }
                                    >
                                      {item1?.title}
                                    </Button>
                                  </li>
                                ))
                              )}
                            </ul>
                          </div>
                        ))}
                    </div>
                  )}
                  {step === 2 && (
                 <div>
                 <div className="mb-4 mt-5">
                   <label htmlFor="title" className="form-label mb-1">
                     Title:
                   </label>
                   <input
                     type="text"
                     id="title"
                     name="title"
                     value={inputData.title}
                     onChange={handleInputChange}
                     className="form-control"
                     placeholder="Enter a compelling title"
                     style={{ borderRadius: '8px', boxShadow: '0 0 5px rgba(0, 0, 0, 0.1)' }}
                     pattern=".{15,50}"
                     title="Title must be between 15 and 50 characters"
                     required
                   />
                   <small className="form-text text-muted">
                     Provide a clear and engaging title for your content.
                   </small>
                 </div>
                 <div className="mb-4">
                   <label htmlFor="description" className="form-label mb-1">
                     Description:
                   </label>
                   <textarea
                     id="description"
                     name="description"
                     value={inputData.description}
                     onChange={handleInputChange}
                     className="form-control"
                     placeholder="Enter a detailed description"
                     style={{ borderRadius: '8px', minHeight: '100px', boxShadow: '0 0 5px rgba(0, 0, 0, 0.1)' }}
                     minLength={50}
                     required
                   />
                   <small className="form-text text-muted">
                     Describe your content in detail to attract viewers.
                   </small>
                 </div>
               
                 <div className="d-flex justify-content-end">
                   <button
                     className="btn btn-secondary me-3 px-4"
                     onClick={handlePrevious}
                     type="button"
                     style={{ borderRadius: '8px' }}
                   >
                     Previous
                   </button>
                   <button
                     className="btn btn-primary px-4 text-white"
                     onClick={handleNext}
                     type="button"
                     style={{ borderRadius: '8px' }}
                   >
                     Next
                   </button>
                 </div>
               </div>
                  )}
                  {step === 3 && (
                    <div className="mt-5">
                      <div className="card-header">
                        <h5>INCLUDE SOME MORE DETAILS</h5>
                      </div>
                      <AddProduct inputData={inputData} idDetail={formData} />
                    </div>
                  )}
                </div>
              </div>
            </div>
            <Ads />
          </div>
        </div>
      </section>
    </>
  );
};

export default AddPost;
