import React, { useEffect } from "react";
import Ads from "../../components/comon/Ads";
import { Link, useParams } from "react-router-dom";
import { useAppContext } from "../../contextApi/AppContext";
import { Card, Table, Container, Row, Col } from "react-bootstrap";
import "./SellerDetails.css";

const SellerDetails = () => {
  const { id } = useParams();

  const { getsellerinfo, sellerinfo } = useAppContext();

  useEffect(() => {
    const dataToSend = {
      sellerId: id,
    };
    getsellerinfo(dataToSend);
  }, [id]);

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-12">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li className="active">Detail Page Of Seller </li>
              </ul>
            </div>
          </aside>
        </article>
      </section>

      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}

            <Col md={10} className="mx-auto">
              {sellerinfo && (
                <Card className="mb-4 shadow-sm">
                  <Row noGutters>
                    <Col md={2} className="text-center">
                      <Card.Img
                        variant="top"
                        style={{ width: "120px", height: "120px" }}
                        src={sellerinfo?.image}
                        alt={sellerinfo.name}
                        className="rounded-circle seller-image"
                      />
                    </Col>
                    <Col md={10}>
                      <Card.Body>
                        <Card.Title>{sellerinfo?.name}</Card.Title>
                        <Card.Subtitle className="mb-2">
                          <strong>Email:</strong> {sellerinfo?.email}
                        </Card.Subtitle>
                        <Card.Text>
                          <strong>Mobile:</strong> {sellerinfo?.mobile} <br />
                          <strong>Address:</strong> {sellerinfo?.address} <br />
                          <strong>Bio:</strong> {sellerinfo?.bio}
                        </Card.Text>
                      </Card.Body>
                    </Col>
                  </Row>
                </Card>
              )}

              {sellerinfo?.seller_own_products &&
                sellerinfo?.seller_own_products.length > 0 && (
                  <Card className="shadow-sm">
                    <Card.Body>
                      <Card.Title>Seller's Products</Card.Title>
                      <Table responsive bordered hover className="mt-3">
                        <thead className="thead-dark">
                          <tr>
                            <th>Title</th>
                            <th>Image</th>
                            <th>Posted On</th>
                          </tr>
                        </thead>
                        <tbody>
                          {sellerinfo.seller_own_products.map((product) => (
                            <tr key={product?._id}>
                              <td>{product?.title}</td>
                              <td>
                                <Link to={`/product/${product?.category_slug}/${product?._id}`}>
                                  <img
                                    src={product?.image}
                                    className="product-image img-thumbnail"
                                    style={{ maxWidth: "150px" }}
                                    alt={product.title}
                                  />
                                </Link>
                              </td>
                              <td>
                                {new Date(
                                  product.createdAt
                                ).toLocaleDateString()}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </Table>
                    </Card.Body>
                  </Card>
                )}
            </Col>

            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>
      </section>
    </>
  );
};

export default SellerDetails;