import React, { useState, useEffect } from "react";
import RealstateProduct from "../components/comon/RealstateProduct";
import Ads from "../components/comon/Ads";
import { useLocation } from "react-router-dom";
import RealstateFilter from "../components/realstate/RealstateFilter";
import { useAppContext } from "../contextApi/AppContext";
import { Pagination } from "@mui/material";
import Stack from "@mui/material/Stack";
import { Skeleton3 } from "../components/loading/Skeleton";
import NoData from "./noData/NoData";
import BreadCrum from "../components/comon/BreadCrum";

const Realstate = () => {
  const {
    property,
    getAttributeFilterList,
    totalItem,
    getProperty,
    listLoading,
    sitelocation
  } = useAppContext();
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;
  const pageCount = Math.ceil(totalItem?.RealEstate / itemsPerPage);
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const sub_id = searchParams.get("sub_category");
  const cat_id = searchParams.get("category_id");
  const search_value = searchParams.get("search");
  const [filterData, setFilterData] = useState([]);
  const [propertyType, setPropertyType] = useState("");
  const [locationSearch, setLocationSearch] = useState("");

  const searchData = {
    address: locationSearch,
    page: currentPage,
    limit: itemsPerPage,
    property_type: propertyType,
  };


  useEffect(() => {
    const fetchData = async () => {
      const dataToSend = {addressName: '' }
      if (sub_id) {
        await getProperty(searchData, sub_id, filterData, dataToSend);
      } else {
        await getProperty(searchData, '', filterData, dataToSend);
      }
    };
    fetchData();
    // eslint-disable-next-line
  }, [
    search_value,
    currentPage,
    sub_id,
    filterData,
    propertyType,
    locationSearch,
  ]);




  useEffect(() => {
    const fetchData = async () => {
      if (sub_id) {
        await getAttributeFilterList({ sub: sub_id });
      }
      if (cat_id) {
        await getAttributeFilterList({ main: cat_id });
      }
    };
    fetchData();
    // eslint-disable-next-line
  }, [search_value, sub_id, cat_id]);

  const updateFilter = (e, attr, value) => {
    const val = value || e.target.value || "";
    const checked = e.target.checked;
    console.log(val);
    if (val === "any") {
      const updatedItems = filterData.filter(
        (selectedItem) => selectedItem.attribute !== attr
      );
      setFilterData(updatedItems);
    } else {
      if (checked || val) {
        setFilterData([...filterData, { attribute: attr, value: val }]);
      }
    }
  };

  const handlePropertyTypeChange = (e) => {
    setPropertyType(e.target.value);
  };

  const handleLocationChange = (e) => {
    setLocationSearch(e.target.value);
  };

  // useEffect(() => {
  //   console.log(filterData)
  // }, [filterData])

  return (
    <>
      <BreadCrum title={"Real Estate List Page"} param={"Real Estate"} />

      {/* new work start here */}
      <div className="container">
        <div className="filterBox">
          <ul>
            <li>
              <div className="form-check form-check-inline">
                <input
                  className="form-check-input"
                  type="radio"
                  name="inlineRadioOptions"
                  id="inlineRadio1"
                  defaultValue="option1"
                  value="Buy"
                  onChange={handlePropertyTypeChange}
                />
                <label className="form-check-label" htmlFor="inlineRadio1">
                  Buy
                </label>
              </div>
              <div className="form-check form-check-inline">
                <input
                  className="form-check-input"
                  type="radio"
                  name="inlineRadioOptions"
                  id="inlineRadio2"
                  defaultValue="option2"
                  value="Rent"
                  onChange={handlePropertyTypeChange}
                />
                <label className="form-check-label" htmlFor="inlineRadio2">
                  Rent
                </label>
              </div>
              <div className="form-check form-check-inline">
                <input
                  className="form-check-input"
                  type="radio"
                  name="inlineRadioOptions"
                  id="inlineRadio3"
                  defaultValue="option3"
                  value="Lease"
                  onChange={handlePropertyTypeChange}
                />
                <label className="form-check-label" htmlFor="inlineRadio3">
                  Lease
                </label>
              </div>
            </li>
            <li>
              <div class="input-group">
                <span class="input-group-text" id="basic-addon1">
                  <i class="fas fa-map-marker-alt text-primary"></i>
                </span>
                <input
                  type="text"
                  class="form-control"
                  placeholder="Selcet Location"
                  value={locationSearch}
                  onChange={handleLocationChange}
                />
              </div>
            </li>
            {/* <li>
            <select class="form-control" name="" id="">
              <option value="">Option 1</option>
              <option value="">Option 2</option>
              <option value="">Option 3</option>
              <option value="">Option 4</option>
              <option value="">Option 5</option>
            </select>
          </li>
          <li>
            <select class="form-control" name="" id="">
              <option value="">Option 1</option>
              <option value="">Option 2</option>
              <option value="">Option 3</option>
              <option value="">Option 4</option>
              <option value="">Option 5</option>
            </select>
          </li> */}
            <li>
              <button className="btn btn-primary text-white" type="button">
                <i class="fas fa-save"></i> Save Search
              </button>
            </li>
          </ul>
        </div>
      </div>
      {/* new work end here */}

      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
            {/* left part start */}
            <div className="col-md-2">
              <RealstateFilter onFilter={updateFilter} />
            </div>

            {/* left part end */}
            {/* right part start */}
            <div className="col-md-8">
              {/* product item start */}
              {listLoading.RealEstate ? (
                Array.from({ length: 3 }).map((_, index) => (
                  <Skeleton3 key={index} />
                ))
              ) : property.length === 0 ? (
                <NoData
                  des={
                    "Please check the spelling or try searching for something else. Thank you!."
                  }
                />
              ) : (
                property.map((item, index) => (
                  <RealstateProduct key={index} item={item} />
                ))
              )}
              {/* product item end */}
              {/* pagination */}
              <div align="center">
                <Stack spacing={2}>
                  <Pagination
                    count={pageCount}
                    page={currentPage}
                    onChange={(event, value) => setCurrentPage(value)}
                    color="primary"
                    variant="outlined"
                    shape="rounded"
                    boundaryCount={2}
                    siblingCount={1}
                  />
                </Stack>
              </div>
              {/* pagination end */}
            </div>
            {/* right part end */}
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>
      </section>
    </>
  );
};

export default Realstate;