import React, { useEffect, useState } from "react";
import Ads from "./../components/comon/Ads";
import GalerySlider from "../components/sliders/GalerySlider";
import { Link, useParams } from "react-router-dom";
import { useAppContext } from "../contextApi/AppContext";
import CallAction from "../components/comon/CallAction";
import ShareModal from "../components/modal/ShareModal";
import { FaHeart, FaRegHeart, FaShareAlt, FaTrash } from "react-icons/fa";
const RealstateDetail = ({ initialDetail }) => {
  const { id } = useParams();
  const {
    getPropertyDetail,
    propertyDetail,
    setPropertyDetail,
    wishListAdd,
    wishListRemove,
    reletedList,
    getReletedProduct,
    userData,
    productrating,
    getreviews,
    reviews,
    reviewDelete,
  } = useAppContext();

  const [color, setColor] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [rating, setRating] = useState(0);
  const [review, setReview] = useState("");
  const [images, setImages] = useState([]);
  const [previewImages, setPreviewImages] = useState([]);

  const handleRatingChange = (newRating) => {
    setRating(newRating);
    // console.log('New rating set:', rating);
  };

  const handleReviewChange = (event) => {
    setReview(event.target.value);
  };

  const handleImageChange = (event) => {
    const files = Array.from(event.target.files);
    setImages(files);
    setPreviewImages(files.map((file) => URL.createObjectURL(file)));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const formData = new FormData();
    formData.append("productId", product_id);
    formData.append("rating", rating);
    formData.append("review", review);
    images.forEach((image, index) => {
      formData.append(`attachments[${index}]`, image);
    });

    productrating(formData);

    setRating(0);
    setReview("");
    setImages([]);
    setPreviewImages([]);
  };

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  useEffect(() => {
    const fetchData = async () => {
      await getPropertyDetail(id);
    };
    if (!initialDetail && id) {
      fetchData();
    }
    if (!!initialDetail && !!initialDetail.data && !!initialDetail.data._id) {
      setPropertyDetail(initialDetail);
    }
    // eslint-disable-next-line
  }, [id, initialDetail]);

  const {
    description,
    image_1,
    image_2,
    image_3,
    photo,
    title,
    product_id,
    attribute_values,
    isWishlist,
    category_id,
    category_name,
    category_slug,
    sub_category_id,
    userId,
    lat,
    lng,
    address,
    createdAt,
  } = propertyDetail.data || {};

  useEffect(() => {
    if (product_id) {
      getreviews(product_id);
    }
    // eslint-disable-next-line
  }, [product_id]);

  const img = [photo, image_1, image_2, image_3];

  useEffect(() => {
    if (isWishlist !== undefined) {
      setColor(isWishlist);
    }
  }, [isWishlist]);

  const addWhishlist = (id) => {
    if (!color) {
      wishListAdd(id);
      setColor(true);
    } else {
      wishListRemove(id);
      setColor(false);
    }
  };

  useEffect(() => {
    if (product_id && category_id) {
      getReletedProduct(category_id, sub_category_id, product_id);
    }
    // eslint-disable-next-line
  }, [product_id, category_id, sub_category_id]);

  const date = new Date(createdAt);

  // Extract day, month, and year
  const day = String(date.getUTCDate()).padStart(2, "0");
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const year = date.getUTCFullYear();

  // Format as DD MM YYYY
  const formattedDate = `${day}/${month}/${year}`;

  const handleDelete = (id) => {
    const deleteConfirm = window.confirm(
      "Are you sure you want to delete this Review?"
    );
    if (deleteConfirm) {
      const dataToSend = {
        product_id: product_id,
        reviewId: id,
      };
      reviewDelete(dataToSend);
    }
  };

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-12">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li>
                  <Link to={`/${category_slug}?category_id=${category_id}`}>
                    {category_name}
                  </Link>
                </li>
                <li className="active"> Detail Page Of {title}</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            <Ads />
            {propertyDetail.isLoad && (
              <div className="col-md-10 d-flex justify-content-center ">
                <div className="spinner-grow text-info my-4" role="status">
                  <span className="sr-only">Loading...</span>
                </div>
              </div>
            )}
            {!propertyDetail.isLoad && (
              <div className="col-md-10">
                <div className="row">
                  <div className="col-md-8">
                    <div className="card" style={{ height: "144vh" }}>
                      <div className="card-header">
                        <h5 className="">{title} </h5>
                      </div>
                      <div className="card-body">
                        <GalerySlider img={img} />
                      </div>
                    </div>
                  </div>
                  <div className="col-md-4">
                    <div className="card card-sm mb15">
                      <div className="card-body p5">
                        <ul className="list-group list-group-horizontal list-inline">
                          <li className="list-group-item border-0 px-1">
                            <div className="iconWish">
                              <FaShareAlt
                                className="text20 text-primary" // Adjust the class as needed
                                onClick={openModal}
                              />
                              <ShareModal
                                isOpen={isModalOpen}
                                onClose={closeModal}
                              />
                            </div>
                          </li>
                          <li className="list-group-item border-0 px-1">
                            {userData._id === userId ? (
                              ""
                            ) : (
                              <div
                                className="iconWish"
                                onClick={() => addWhishlist(product_id)}
                              >
                                {color ? (
                                  <FaHeart className="text-danger text20" />
                                ) : (
                                  <FaRegHeart className="text20" />
                                )}
                              </div>
                            )}
                          </li>
                        </ul>
                      </div>
                    </div>
                    {/* location */}
                    <div className="card card-sm mb15">
                      <div className="card-body p8">
                        <h5 className="mb0 text16 theme-text">
                          <i className="fa fa-calendar" /> <b>Posted On</b>{" "}
                          {formattedDate}
                        </h5>
                        <p className="text-muted mb5">
                          <b>Location :</b> {address}
                        </p>
                        <div>
                          <iframe
                            title={title}
                            allowFullScreen
                            height="350"
                            loading="lazy"
                            referrerPolicy="no-referrer-when-downgrade"
                            src={`https://www.google.com/maps/embed/v1/view?key=AIzaSyAbznYqeVfwfeh0DQdKFF4tFAq276hU6cY&center=${lat},${lng}2&zoom=15`}
                            style={{
                              border: "0",
                            }}
                            width="100%"
                          />
                        </div>
                      </div>
                    </div>

                    <div>
                      {userData._id === userId ? (
                        ""
                      ) : (
                        <CallAction
                          peerUser={userId}
                          realestateId={1}
                          details={propertyDetail?.data}
                          productId={product_id}
                        />
                      )}
                    </div>
                    <div className="card">
                      <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="mb-0">Seller Information</h5>
                        <Link
                          to={`/seller-info/${propertyDetail?.data.seller_details?._id}`}
                        >
                          <img
                            src={propertyDetail?.data?.seller_details?.image}
                            alt="Seller"
                            className="rounded-circle"
                            style={{ width: "40px", height: "40px" }}
                          />
                        </Link>
                      </div>
                      <div className="card-body">
                        <p>
                          <strong>Seller Name:</strong>{" "}
                          <span>
                            {propertyDetail?.data.seller_details?.name}
                          </span>
                        </p>
                        <p>
                          <strong>Mobile:</strong>{" "}
                          <span>
                            {propertyDetail?.data.seller_details?.mobile}
                          </span>
                        </p>
                        <p>
                          <strong>Email:</strong>{" "}
                          <span>
                            {propertyDetail?.data.seller_details?.email}
                          </span>
                        </p>
                        <p>
                          <strong>Address:</strong>{" "}
                          <span>
                            {propertyDetail?.data.seller_details?.address}
                          </span>
                        </p>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="col-md-12 mt10">
                  <div className="card">
                    <div className="card-header">
                      <h4>Rate this product:</h4>
                    </div>
                    <div className="card-body">
                      <div className="rating mt-4">
                        {[...Array(5)].map((star, index) => (
                          <button
                            key={index}
                            type="button"
                            className={`btn btn-link ${
                              index < rating ? "text-warning" : ""
                            }`}
                            onClick={() => handleRatingChange(index + 1)}
                          >
                            <i className="fas fa-star"></i>
                          </button>
                        ))}
                      </div>
                      <form onSubmit={handleSubmit} className="mt-4">
                        <div className="form-group">
                          <label htmlFor="review">Review:</label>
                          <textarea
                            id="review"
                            className="form-control"
                            value={review}
                            onChange={handleReviewChange}
                          ></textarea>
                        </div>
                        <div className="form-group mt-3">
                          <label htmlFor="images">Upload Images:</label>
                          <input
                            type="file"
                            id="images"
                            className="form-control"
                            multiple
                            onChange={handleImageChange}
                          />
                          <div className="preview-images mt-3">
                            {previewImages.map((src, index) => (
                              <img
                                key={index}
                                src={src}
                                alt="Preview"
                                className="img-thumbnail mr-2"
                                style={{ width: "100px", height: "100px" }}
                              />
                            ))}
                          </div>
                        </div>
                        <button type="submit" className="btn btn-primary mt-3">
                          Submit Review
                        </button>
                      </form>
                    </div>
                  </div>

                  <div className="mt-5">
                    <h4>Reviews:</h4>
                    {Array.isArray(reviews.data) &&
                      reviews.data.map((review) => (
                        <div
                          className="card mb-3 shadow-sm"
                          key={review._id}
                          style={{ position: "relative" }}
                        >
                          <div className="card-body">
                            {userData._id === review.userId && (
                              <FaTrash
                                className="text-danger"
                                style={{
                                  cursor: "pointer",
                                  position: "absolute",
                                  top: "10px",
                                  right: "10px",
                                }}
                                onClick={() => handleDelete(review._id)}
                              />
                            )}
                            <div className="d-flex align-items-center mb-3">
                              <img
                                src={review.user_img}
                                alt="User"
                                className="rounded-circle mr-3"
                                style={{ width: "50px", height: "50px" }}
                              />
                              <div
                                className="user-profileinfo"
                                style={{ marginLeft: "10px" }}
                              >
                                <h6 className="mb-0">{review.user_name}</h6>
                                <small className="text-muted">
                                  {new Date(
                                    review.createdAt
                                  ).toLocaleDateString()}
                                </small>
                              </div>
                            </div>
                            <div className="rating">
                              {[...Array(5)].map((star, index) => (
                                <i
                                  key={index}
                                  className={`fas fa-star ${
                                    index < review.rating
                                      ? "text-warning"
                                      : "text-secondary"
                                  }`}
                                ></i>
                              ))}
                            </div>
                            <p className="mt-3">{review.review}</p>
                            <div className="mt-3">
                              {review.attachments.map((src, index) => (
                                <img
                                  key={index}
                                  src={src}
                                  alt="Review attachment"
                                  className="img-thumbnail mr-2 mb-2"
                                  style={{ width: "100px", height: "100px" }}
                                />
                              ))}
                            </div>
                          </div>
                        </div>
                      ))}
                  </div>
                </div>

                <div className="col-md-12 mt10">
                  <div className="card">
                    <div className="card-body">
                      <div className="row">
                        <div className="col-md-4">
                          <div className="property-attributes">
                            <div className="attr-list">
                              <h4>Property Specification</h4>
                              <table className="table table-bordered table-striped">
                                <tbody>
                                  {Array.isArray(attribute_values) &&
                                    attribute_values.map(
                                      (item) =>
                                        item.value && (
                                          <tr key={item._id}>
                                            <td>
                                              <strong>{item.attribute}</strong>
                                            </td>
                                            <td>{item.value}</td>
                                          </tr>
                                        )
                                    )}
                                </tbody>
                              </table>
                            </div>
                          </div>
                        </div>
                        <div className="col-md-8">
                          <div className="property-description">
                            <h4>{title}</h4>
                            <div className="mt25">
                              <h5>Property Description :</h5>
                              <p>{description} </p>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="row">
                  <div className="col-md-12">
                    <h5 className="mt-3">Related Field</h5>
                    <hr className="mt0" />
                  </div>
                  {/* item start */}
                  {Array.isArray(reletedList) &&
                    reletedList.map((item) => {
                      return (
                        <div className="col-md-6" key={item._id}>
                          <div className="card mb-3" style={{ maxWidth: 540 }}>
                            <div className="row g-0">
                              <Link
                                to={`/product/related-product/${item._id}`}
                                className="col-md-4"
                              >
                                <img
                                  src={item.image}
                                  className="img-fluid rounded-start"
                                  style={{ height: "180px" }}
                                  alt="..."
                                />
                              </Link>
                              <div className="col-md-8">
                                <div className="card-body">
                                  <h5 className="card-title">{item.title}</h5>
                                  <p
                                    className="mt10"
                                    style={{
                                      overflow: "hidden",
                                      textOverflow: "ellipsis",
                                      display: "-webkit-box",
                                      WebkitLineClamp: 3,
                                      WebkitBoxOrient: "vertical",
                                    }}
                                  >
                                    {item.description}
                                  </p>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  {/* item end */}
                </div>
              </div>
            )}

            <Ads />
          </article>
        </article>
      </section>
    </>
  );
};

export default RealstateDetail;
