import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useAppContext } from "../../contextApi/AppContext";
import noPostar from "../../assets/no-poster.png";

const Jobs = ({ item }) => {
  const {
    jobList,
    wishListAdd,
    wishListRemove,
    userData,
    getJobList,
    sitelocation,
  } = useAppContext();
  const [colorMap, setColorMap] = useState({});

  useEffect(() => {
    const dataToSend = {
      addressName: sitelocation,
    };
    getJobList("", "", "", dataToSend);
    // eslint-disable-next-line
  }, [sitelocation]);

  const addWhishlist = (id) => {
    if (colorMap[id]) {
      wishListRemove(id);
      const filtered = { ...colorMap };
      filtered[id] = false;
      setColorMap(filtered);
    } else {
      wishListAdd(id);
      setColorMap((prevColorMap) => ({
        ...prevColorMap,
        [id]: !prevColorMap[id],
      }));
    }
  };

  useEffect(() => {
    if (jobList && Array.isArray(jobList)) {
      let check = {};
      jobList.forEach((list) => {
        check[list.product_id] = list.isWishlist;
      });
      setColorMap(check);
    }
  }, [jobList]);

  return (
    <>
      <section className="">
        <article className="container pt-4 pb-4">
          <div className="d-flex justify-content-between align-items-center">
            <h4 className="m-0">{item.title}</h4>
            <Link
              className="text text-decoration-none "
              to={`/${item.slug}?category_id=${item._id}`}
              onMouseEnter={(e) =>
                (e.target.style.color = "var(--theme-color)")
              }
              onMouseLeave={(e) => (e.target.style.color = "black")}
            >
              View All
            </Link>
          </div>
          <aside className="row pt-2">
            {/* item start */}
            {Array.isArray(jobList) &&
              jobList.slice(0, 4).map((jobItem) => (
                <div className="col-md-3 col-12 proBx" key={jobItem._id}>
                  <div className="card mb-3">
                    <div className="imgBx">
                      <Link to={`/job-detail/${jobItem._id}`}>
                        <img
                          src={jobItem.image || noPostar}
                          className="card-img-top allImg"
                          alt=""
                        />
                      </Link>
                      {jobItem.userId === userData._id ? (
                        ""
                      ) : (
                        <div
                          className="iconWish"
                          onClick={() => addWhishlist(jobItem.product_id)}
                        >
                          <i
                            className={
                              colorMap[jobItem.product_id]
                                ? "fa fa-heart text-danger"
                                : "fa fa-heart-o"
                            }
                          />
                        </div>
                      )}
                    </div>
                    <div className="card-body">
                      <h5 className="card-title">
                        <Link to={`/job-detail/${jobItem._id}`}>
                          {jobItem?.title}
                        </Link>
                      </h5>
                      <p
                        style={{
                          overflow: "hidden",
                          textOverflow: "ellipsis",
                          display: "-webkit-box",
                          WebkitLineClamp: 3,
                          WebkitBoxOrient: "vertical",
                        }}
                      >
                        {jobItem.description}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            {/* item end */}
          </aside>
        </article>
      </section>
    </>
  );
};

export default Jobs;
