import React, { useEffect, useState } from "react";
import Ads from "../../../components/comon/Ads";
import { Link, useParams } from "react-router-dom";
import { Button } from "react-bootstrap";
import { useAppContext } from "../../../contextApi/AppContext";
import SubscriptionPrice from "../../../components/modal/SubscriptionPrice";

const PostUpdate = () => {
  const {
    getMyPostListDetail,
    myPostDetail,
    updateMyPost,
    userData,
    check,
    packagesList,
    getUserplan,
  } = useAppContext();
  const { id } = useParams();
  const [image, setImage] = useState("");
  const [photo, setPhoto] = useState("");
  const [image_1, setImage_1] = useState("");
  const [image_2, setImage_2] = useState("");
  const [image_3, setImage_3] = useState("");
  const [attData, setAttData] = useState([]);
  const [isImage, setIsImage] = useState(false);
  const [preview, setPreview] = useState([]);
  const [showModal, setShowModal] = useState(false);

  const [formState, setFormState] = useState({
    title: "",
    description: "",
    attribute_values: [],
    image: "",
    photo: "",
    image_1: "",
    image_2: "",
    image_3: "",
    product_price: "",
    category_name: [],
  });

  const filteredPackages = packagesList?.filter((item) => item.type === "Zoom");

  const membership_id = userData?.membership_details?.find(
    (data) => data.membership_id === filteredPackages[0]?._id
  );

  console.log(membership_id?.membership_status);
  const handleChange = (e, index, attId) => {
    const { name, value, files } = e.target;

    if (name === "attribute_value") {
      const updatedAttributeValues = [...formState.attribute_values];
      updatedAttributeValues[index].value = value;

      setFormState((prevState) => ({
        ...prevState,
        attribute_values: updatedAttributeValues,
      }));
    } else if (name === "product_price") {
      setFormState((prevState) => ({
        ...prevState,
        [name]: value,
      }));
    } else if (
      ["photo", "image", "image_1", "image_2", "image_3"].includes(name)
    ) {
      const [file] = files;
      if (file) {
        switch (name) {
          case "photo":
            setPhoto(e.target.files[0]);
            break;
          case "image":
            setImage(e.target.files[0]);
            break;
          case "image_1":
            setImage_1(e.target.files[0]);
            break;
          case "image_2":
            setImage_2(e.target.files[0]);
            break;
          case "image_3":
            setImage_3(e.target.files[0]);
            break;
          default:
            break;
        }
        setFormState((prevState) => ({
          ...prevState,
          [name]: file,
        }));

        setPreview((prevState) => ({
          ...prevState,
          [name]: URL.createObjectURL(file),
        }));
      }
    } else {
      setFormState((prevState) => ({
        ...prevState,
        [name]: value,
      }));

      setAttData({
        ...attData,
        [attId]: value,
      });
    }
  };

  useEffect(() => {
    if (
      myPostDetail?.category_name === "Jobs" ||
      myPostDetail?.category_name === "Freelancer" ||
      myPostDetail?.category_name === "Lessons & Courses"
    ) {
      setIsImage(true);
    } else {
      setIsImage(false);
    }
  }, [myPostDetail]);

  const handleSubmit = (e) => {
    e.preventDefault();
    const {
      title,
      description,
      photo,
      image,
      image_1,
      image_2,
      image_3,
      attribute_values,
      product_price,
    } = formState;

    if (isImage && !image) {
      alert("Please upload an image");
      return;
    }

    const dataPost = new FormData();
    dataPost.append("title", title);
    dataPost.append("description", description);
    if (!isImage) {
      dataPost.append("photo", photo || "");
      dataPost.append("image_1", image_1 || "");
      dataPost.append("image_2", image_2 || "");
      dataPost.append("image_3", image_3 || "");
    } else {
      dataPost.append("image", image || "");
    }
    dataPost.append("product_price", product_price || "");
    attribute_values.forEach((item, index) => {
      if (item.attribute !== "title" && item.attribute !== "description") {
        dataPost.append(
          `attributeData[${index}][attribute_id]`,
          item.attribute_id
        );
        dataPost.append(`attributeData[${index}][value]`, item.value);
      }
    });
    updateMyPost(id, dataPost);
  };

  useEffect(() => {
    setFormState({
      title: myPostDetail.title,
      description: myPostDetail.description,
      attribute_values: myPostDetail.attribute_values,
      image: myPostDetail.image,
      photo: myPostDetail.photo,
      image_1: myPostDetail.image_1,
      image_2: myPostDetail.image_2,
      image_3: myPostDetail.image_3,
      product_price: myPostDetail?.product_price,
    });
  }, [myPostDetail]);

  // console.log(myPostDetail, 'formState')

  useEffect(() => {
    getMyPostListDetail(id);
  }, [id]);

  useEffect(() => {
    getUserplan();
    // eslint-disable-next-line
  }, []);

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-6">
              <h4>SELECTED CATEGORY</h4>
            </div>
            <div className="col-md-6">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li>
                  <Link className="active" to="/my-post">
                    My Post
                  </Link>
                </li>
                <li className="active">Update Product</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody">
        <article className="container-fluid">
          <article className="row">
            <Ads />
            <div className="col-md-10">
              <div className="card">
                <div className="card card-header">
                  <h5 className="text-center">Update Product</h5>
                </div>
                <div className="card card-body border-0">
                  <form onSubmit={handleSubmit} encType="multipart/form-data">
                    <div className="mb20" style={{ maxWidth: "500px" }}>
                      <h6>Title</h6>
                      <input
                        type="text"
                        name="title"
                        id="title"
                        value={formState.title}
                        onChange={handleChange}
                        className="form-control"
                      />
                    </div>
                    <div className="mb20">
                      <h6>Description</h6>
                      <textarea
                        type="text"
                        name="description"
                        id="description"
                        value={formState.description}
                        onChange={handleChange}
                        className="form-control min-vh-40"
                      />
                    </div>
                    <div className="radioBx mb20">
                      <div className="row">
                        {Array.isArray(formState.attribute_values) &&
                          formState.attribute_values.map((item, index) => (
                            <div className="col-md-6 mt30" key={item._id}>
                              <label
                                style={{
                                  fontWeight: "bold",
                                  fontSize: "1em",
                                }}
                              >
                                {item.attribute}
                              </label>
                              <input
                                type="text"
                                name="attribute_value"
                                id={`attribute_value_${index}`}
                                value={item.value}
                                onChange={(e) =>
                                  handleChange(e, index, item.attribute_id)
                                }
                                className="form-control mt-2"
                              />
                            </div>
                          ))}
                      </div>
                    </div>
                    <div>
                      {myPostDetail.category_id ===
                      "6548c04e1e40c887cc280d07" ? (
                        <div className="App d-flex flex-column">
                          <h6>Course Price</h6>
                          <div className="d-flex align-items-center mb-3">
                            <div className="form-group me-3 mb-0">
                              <input
                                type="number"
                                className="form-control"
                                id="coursePriceAmount"
                                name="product_price"
                                value={formState.product_price}
                                onChange={handleChange}
                                placeholder="Enter amount"
                                disabled={myPostDetail?.product_plans || check}
                              />
                            </div>
                            {membership_id?.membership_status && (
                              <button
                                className="btn btn-outline-primary"
                                onClick={(e) => {
                                  e.preventDefault();
                                  if (myPostDetail?.product_plans === null) {
                                    setShowModal(true);
                                  }
                                }}
                                disabled={myPostDetail?.product_plans || check}
                              >
                                {myPostDetail?.product_plans || check
                                  ? "Plan Selected"
                                  : "Add Subscription Plan"}
                              </button>
                            )}
                          </div>
                          <SubscriptionPrice
                            show={showModal}
                            handleClose={() => setShowModal(false)}
                            product_id={id}
                            category_id={myPostDetail.category_id}
                          />
                        </div>
                      ) : (
                        ""
                      )}
                    </div>
                    {!isImage ? (
                      <>
                        <h5 className="m0 text-center mt50">
                          UPLOAD UP TO 4 PHOTOS
                        </h5>
                        <div className="row mt10">
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="photo"
                                id="photo"
                                style={{ display: "none" }}
                                onChange={handleChange}
                              />
                              <label htmlFor="photo">
                                <img
                                  src={preview.photo || formState.photo}
                                  height={70}
                                  width={100}
                                  alt=""
                                />
                              </label>
                            </div>
                          </div>
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="image_1"
                                id="img1"
                                style={{ display: "none" }}
                                onChange={handleChange}
                              />
                              <label htmlFor="img1">
                                <img
                                  height={70}
                                  width={100}
                                  src={preview.image_1 || formState.image_1}
                                  alt="Img_1"
                                />
                              </label>
                            </div>
                          </div>
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="image_2"
                                id="img2"
                                onChange={handleChange}
                                style={{ display: "none" }}
                              />
                              <label htmlFor="img2">
                                <img
                                  height={70}
                                  width={100}
                                  src={preview.image_2 || formState.image_2}
                                  alt="image_2"
                                />
                              </label>
                            </div>
                          </div>
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="image_3"
                                id="img3"
                                style={{ display: "none" }}
                                onChange={handleChange}
                              />
                              <label htmlFor="img3">
                                <img
                                  height={70}
                                  width={100}
                                  src={preview.image_3 || formState.image_3}
                                  alt="image_3"
                                />
                              </label>
                            </div>
                          </div>
                        </div>
                      </>
                    ) : (
                      <>
                        <h5 className="m30 text-center">UPLOAD file</h5>
                        <div className="row justify-content-center">
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="image"
                                id="img"
                                onChange={handleChange}
                                style={{ display: "none" }}
                              />
                              <label htmlFor="img">
                                <img
                                  height={70}
                                  width={100}
                                  src={preview.image || formState.image}
                                  alt=""
                                />
                              </label>
                            </div>
                          </div>
                        </div>
                      </>
                    )}
                    <Button type="submit" className="text text-white mt30">
                      Submit
                    </Button>
                  </form>
                </div>
              </div>
            </div>
            <Ads />
          </article>
        </article>
      </section>
    </>
  );
};

export default PostUpdate;
