import React, { useEffect, useState } from "react";
import Ads from "./../components/comon/Ads";
import { Link, useNavigate, useParams } from "react-router-dom";
import LessonItemRelated from "../components/lessons-courses/LessonItemRelated";
import { useAppContext } from "../contextApi/AppContext";
import ShareModal from "../components/modal/ShareModal";
import ScheduleMeetingModal from "../components/modal/ScheduleMeetingModal";
import { Button, Spinner, Table } from "react-bootstrap";
import { FaCalendarAlt } from "react-icons/fa";
import { loadStripe } from "@stripe/stripe-js";
import { toast } from "react-toastify";
import axios from "axios";
const stripePromise = loadStripe(
  "pk_test_51PRWS708i8J7Bqoukp7NUitKQ5wmhOokDfktkMWnRc57EICz4HyYIp8n8soyRDmwACcflugDI91nAGEazLs3QOQ7008GpqmAmj"
);

const LessonCoursesDetail = ({ initialDetail }) => {
  const { id } = useParams();
  const {
    getLessonDetail,
    lessonDetail,
    userData,
    getReletedProduct,
    reletedList,
    setlessonDetail,
    createFreePayment,
    token,
    baseURL,
  } = useAppContext();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalShow, setModalShow] = useState(false);
  const [loader, setLoader] = useState(false);
  const handleShow = () => setModalShow(true);
  const handleClose = () => setModalShow(false);
  const navigate = useNavigate()

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  useEffect(() => {
    const fetchData = async () => {
      await getLessonDetail(id);
    };
    if (!initialDetail && id) {
      fetchData();
    }
    if (!!initialDetail && !!initialDetail.data && !!initialDetail.data._id) {
      setlessonDetail(initialDetail);
    }
    // eslint-disable-next-line
  }, [id, initialDetail]);
  const {
    description,
    title,
    attribute_values,
    category_name,
    category_id,
    category_slug,
    product_id,
    sub_category_id,
    userId,
    product_plans,
    purchase_mode,
    user_subscription,
    image,
    upcoming_meetings,
  } = lessonDetail?.data || {};

  // console.log(attribute_values, 'attribute_values',)
  const createSubsPayment = async (plan_id) => {
    try {
      setLoader(true);
      if (!token) {
        toast.info("Login first");
        return;
      }
      const { data } = await axios.post(
        `${baseURL}/api/subscription/session/create`,
        // { plan_id, redirect: `http://localhost:3000`, id },
        { plan_id, id },
        {
          headers: {
            "Content-Type": "application/json",
            token: token,
          },
        }
      );
      if (data.status === 200) {
        const stripe = await stripePromise;
        const { error } = await stripe.redirectToCheckout({
          sessionId: data.data,
        });
  
        if (error) {
          console.error("Error redirecting to checkout", error);
        }
      }
    } catch (error) {
      toast.error(error?.response?.data?.message || "server error");
    } finally {
      setLoader(false);
    }
  };
  

  const createPaidPayment = async (product_id) => {
    try {
      setLoader(true);
      if (!token) {
        toast.info("Login first");
        return;
      }
      const { data } = await axios.post(
        `${baseURL}/api/payment/session/create `,
        // { product_id, redirect: `http://localhost:3000`, id },
        { product_id, id },
        {
          headers: {
            "Content-Type": "application/json",
            token: token,
          },
        }
      );
      if (data.status === 200) {
        const stripe = await stripePromise;
        const { error } = await stripe.redirectToCheckout({
          sessionId: data.data,
        });
        if (error) {
          console.error("Error redirecting to checkout", error);
        }
      }
    } catch (error) {
      toast.error(error?.response?.data?.message || "server error");
    } finally {
      setLoader(false);
    }
  };

  const handleSubsPayment = () => {
    createSubsPayment(product_plans?._id);
  };

  const handlePaidPayment = () => {
    createPaidPayment(product_id);
    // navigate(`/learn/welcome?courseId=${id}`);
  };

  const handleFreePayment = () => {
    createFreePayment(product_id);
    navigate(`/learn/welcome?courseId=${id}`);
  };

  // function to get data of lessonDetail, videos, Classes, hours
  const getAttributeValue = (attributeName) => {
    if (!Array.isArray(attribute_values)) return null;
    const attribute = attribute_values?.find(
      (item) => item.attribute === attributeName
    );
    if (attribute && attribute.value) {
      const number = parseInt(attribute?.value);
      if (!isNaN(number)) {
        return number;
      }
    }
    return null;
  };

  const lessons = getAttributeValue("No. of Lessons");
  const videos = getAttributeValue("No. of Videos");
  const Classes = getAttributeValue("No. of Classes");
  const hours = getAttributeValue("No. of Hours");

  // function to get all Video link
  const getVideoLinks = () => {
    if (!Array.isArray(attribute_values)) return [];
    return attribute_values.filter((item) => {
      return item.value.startsWith("https://youtu.be");
    });
  };
  const videoLinks = getVideoLinks();

  const convertToEmbedLink = (youtubeLink) => {
    const videoId = youtubeLink.split("/").pop().split("?")[0];
    return `https://www.youtube.com/embed/${videoId}`;
  };

  useEffect(() => {
    if (product_id && category_id) {
      getReletedProduct(category_id, sub_category_id, product_id);
    }
    // eslint-disable-next-line
  }, [product_id, category_id, sub_category_id]);

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-12">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li>
                  <Link to={`/${category_slug}?category_id=${category_id}`}>
                    {category_name}
                  </Link>
                </li>
                <li className="active">Detail Page Of {title}</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
            {/* mid body part start */}
            {lessonDetail.isLoad && (
              <div className="col-md-10 d-flex justify-content-center ">
                <div className="spinner-grow text-info my-4" role="status">
                  <span className="sr-only">Loading...</span>
                </div>
              </div>
            )}

            {!lessonDetail.isLoad && (
              <div className="col-md-10">
                {/* heading box part start */}
                <div className="row">
                  <div className="col-md-8">
                    <h2 className="mb-3">{title}</h2>
                  </div>
                  <div className="col-md-4" align="right">
                    <div className="col-md-4" align="right">
                      <i
                        className="fa fa-share-alt text20 "
                        onClick={openModal}
                      />
                      <ShareModal isOpen={isModalOpen} onClose={closeModal} />
                    </div>
                  </div>
                </div>
                <hr className="mt0" />
                {/* heading box part end */}
                <div className="row mb-3">
                  <div className="col-md-8">
                    <div
                      className="card freelanceDtls mb-3 "
                      style={{ background: "#feffdb" }}
                    >
                      <div className="card-body">
                        <ul>
                          <li>
                            <i className="fa fa-file-text-o" />
                            <h6>
                              <b>{lessons || "Not Mentioned"}</b>
                            </h6>
                            <p>Lessons</p>
                          </li>
                          <li>
                            <i className="fa fa-play" />
                            <h6>
                              <b>{videos || "Not Mentioned"}</b>
                            </h6>
                            <p>Videos</p>
                          </li>
                          <li>
                            <i className="fa fa-question" />
                            <h6>
                              <b>{Classes || "Not Mentioned"}</b>
                            </h6>
                            <p>Classes</p>
                          </li>
                          <li>
                            <i className="fa fa-clock-o" />
                            <h6 className="text-success">
                              <b>{hours ? `${hours} : 00` : "Not Mentioned"}</b>
                            </h6>
                            <p>Hours</p>
                          </li>
                        </ul>
                      </div>
                    </div>
                    <div className="card mb-3">
                      <div className="card-body">
                        <h3 className="card-title">Description for {title}</h3>
                        {description}
                        <hr />

                        {userData._id !== userId ? (
                          <div>
                            <h3 className="mt-4">Upcoming Classes</h3>
                            {Array.isArray(upcoming_meetings) &&
                            upcoming_meetings.length > 0 ? (
                              <Table striped bordered hover className="mt-3">
                                <thead>
                                  <tr>
                                    <th>Date</th>
                                    <th>Time</th>
                                    <th>Subject</th>
                                  </tr>
                                </thead>
                                <tbody>
                                  {Array.isArray(upcoming_meetings) &&
                                    upcoming_meetings.map(
                                      (classItem, index) => {
                                        const dateObj = new Date(
                                          classItem?.meetingAt
                                        );
                                        const year = dateObj.getFullYear();
                                        const month = String(
                                          dateObj.getMonth() + 1
                                        ).padStart(2, "0"); // Months are zero-indexed
                                        const day = String(
                                          dateObj.getDate()
                                        ).padStart(2, "0");
                                        const formattedDate = `${year}-${month}-${day}`;
                                        const hours = String(
                                          dateObj.getHours()
                                        ).padStart(2, "0");
                                        const minutes = String(
                                          dateObj.getMinutes()
                                        ).padStart(2, "0");
                                        return (
                                          <tr key={index}>
                                            <td>{formattedDate}</td>
                                            <td>{`${hours}:${minutes}`}</td>
                                            <td>{classItem.meeting_agenda}</td>
                                          </tr>
                                        );
                                      }
                                    )}
                                </tbody>
                              </Table>
                            ) : (
                              <p className="">No classes found</p>
                            )}
                          </div>
                        ) : (
                          <div className="App">
                            <h3 className="mt-4">Scheduled Meetings</h3>
                            <Table striped bordered hover className="mt-3">
                              <thead>
                                <tr>
                                  <th>Date</th>
                                  <th>Time</th>
                                  <th>Topic</th>
                                  <th>Action</th>
                                </tr>
                              </thead>
                              <tbody>
                                {Array.isArray(upcoming_meetings) &&
                                  upcoming_meetings.map((classItem, index) => {
                                    const dateObj = new Date(
                                      classItem?.meetingAt
                                    );
                                    const year = dateObj.getFullYear();
                                    const month = String(
                                      dateObj.getMonth() + 1
                                    ).padStart(2, "0");
                                    const day = String(
                                      dateObj.getDate()
                                    ).padStart(2, "0");
                                    const formattedDate = `${year}-${month}-${day}`;
                                    const hours = String(
                                      dateObj.getHours()
                                    ).padStart(2, "0");
                                    const minutes = String(
                                      dateObj.getMinutes()
                                    ).padStart(2, "0");
                                    return (
                                      <tr key={index}>
                                        <td>{formattedDate}</td>
                                        <td>{`${hours}:${minutes}`}</td>
                                        <td>{classItem.meeting_agenda}</td>
                                        <td>
                                          <Button
                                            onClick={() => {
                                              window.open(
                                                classItem.meeting_start_url,
                                                "_blank"
                                              );
                                            }}
                                            variant="success"
                                          >
                                            Start Meeting
                                          </Button>
                                        </td>
                                      </tr>
                                    );
                                  })}
                              </tbody>
                            </Table>
                            <Button
                              className="mt-4"
                              style={{ color: "white" }}
                              variant="primary"
                              onClick={handleShow}
                            >
                              Schedule New Meeting
                            </Button>
                            <ScheduleMeetingModal
                              show={modalShow}
                              handleClose={handleClose}
                              product_id={product_id}
                            />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="col-md-4">
                    <div className="card">
                      <div className="card-body">
                        <div
                          className="card"
                          style={{ width: "20rem", overflow: "hidden" }}
                        >
                          <div style={{ overflow: "hidden" }}>
                            <img
                              src={image}
                              className="card-img-top"
                              alt={""}
                              style={{
                                transition: "transform 0.2s",
                                width: "100%",
                                height: "200px",
                              }}
                              onMouseEnter={(e) =>
                                (e.currentTarget.style.transform = "scale(1.1)")
                              }
                              onMouseLeave={(e) =>
                                (e.currentTarget.style.transform = "scale(1)")
                              }
                            />
                          </div>
                          <div className="card-body">
                            <h6 className="card-title">
                              Plan Name : {product_plans?.plan_name}
                            </h6>
                            <p className="card-text d-flex align-items-center gap-1  ">
                              <FaCalendarAlt />{" "}
                              <span>
                                {product_plans?.plan_interval_count}{" "}
                                {product_plans?.plan_interval}
                              </span>
                            </p>
                            {user_subscription?.user_id === userData._id &&
                            user_subscription?.status === "Active" &&
                            user_subscription?.isEnded === false ? (
                              <p>Already subscribed</p>
                            ) : userData._id === userId ? (
                              <Link
                                to={`/course_instructor?_id=${product_id}`}
                                className="btn btn-primary text-white w-100"
                                variant="primary"
                              >
                                See Details
                              </Link>
                            ) : purchase_mode === "Subscription" ? (
                              <Button
                                className="btn btn-primary text-white w-100"
                                variant="primary"
                                onClick={handleSubsPayment}
                              >
                                {loader ? (
                                  <Spinner animation="border" variant="info" />
                                ) : (
                                  "Subscribe Now"
                                )}
                              </Button>
                            ) : purchase_mode === "Paid" ? (
                              <Button
                                className="btn btn-primary text-white w-100"
                                variant="primary"
                                onClick={handlePaidPayment}
                              >
                                {loader ? (
                                  <Spinner animation="border" variant="info" />
                                ) : (
                                  "Buy Now"
                                )}
                              </Button>
                            ) : (
                              <Button
                                className="btn btn-primary text-white w-100"
                                variant="primary"
                                onClick={handleFreePayment}
                              >
                                Enroll for free
                              </Button>
                            )}
                          </div>
                        </div>
                      </div>
                      <div className="card-body">
                        {videoLinks.map((video, index) => (
                          <div key={index} className="video-responsive">
                            <iframe
                              width="100%"
                              height="100%"
                              src={convertToEmbedLink(video.value)}
                              title={`YouTube video ${index + 1}`}
                              frameBorder="0"
                              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                              allowFullScreen
                            ></iframe>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                  <div className="col-md-12">
                    <h5 className="mt-3">Related Courses</h5>
                    <hr className="mt0" />
                    <div className="row">
                      {Array.isArray(reletedList) &&
                        reletedList.map((item) => (
                          <LessonItemRelated item={item} key={item._id} />
                        ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
            {/* mid body part end */}
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>
      </section>
    </>
  );
};

export default LessonCoursesDetail;
